#!/usr/bin/env python3
"""
Round 116b (culprits-tiles-more), 29 September 2026. Needs nothing before it.

- lawenforcement/gang_infiltration.geojson: 24 documented cases of gangs and
  crime groups inside law enforcement (the map's gang_infiltration row), each
  with the source it quotes and how far it was proven.
- scripts/fertility_policy.py: a build that found nothing (fertility/build.json
  "found": false) tries again on the next daily refresh, not only on Mondays.

Whole files, written as they are; running it twice changes nothing.
Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, sys

FILES = {
 "lawenforcement/gang_infiltration.geojson": "",
 "scripts/fertility_policy.py": ""
}


def main():
    root = pathlib.Path(".")
    if not (root / "scripts").is_dir():
        sys.exit("round116b_tiles: run from the culprits-tiles-more repository root")
    for rel, b64 in FILES.items():
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        data = base64.b64decode(b64)
        if p.exists() and p.read_bytes() == data:
            print(f"round116b_tiles: {rel} already as it should be")
            continue
        p.write_bytes(data)
        print(f"round116b_tiles: wrote {rel}")


if __name__ == "__main__":
    main()
